import{_ as n,a0 as u,w as i,s,ao as l,I as a,x as t,a1 as e,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"為地鐵站構建一個智能停車系統 | LCTT x X-CMD","titleTemplate":false,"description":"為地鐵站構建一個智能停車系統 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為地鐵站構建一個智能停車系統 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為地鐵站構建一個智能停車系統 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220614 Build a Smart Parking System for a Metro Station","title":"為地鐵站構建一個智能停車系統","tag":"202207","desc":""},"relativePath":"202207/20220614 Build a Smart Parking System for a Metro Station.md","filePath":"[post].md"}'),b={name:"202207/20220614 Build a Smart Parking System for a Metro Station.md"};function d(m,r,g,c,y,f){const o=u("Link");return i(),s("div",null,[r[15]||(r[15]=l('<h1 id="為地鐵站構建一個智能停車系統" tabindex="-1">為地鐵站構建一個智能停車系統 <a class="header-anchor" href="#為地鐵站構建一個智能停車系統" aria-label="Permalink to “為地鐵站構建一個智能停車系統”">​</a></h1><blockquote><p>本文將幫助你設計一個基於 Web 的應用程序，使用 Node-RED 為地鐵站的汽車提供一個自動智能停車系統。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Smart-car-parking.jpg" alt="Smart car parking"></p><p>Web 應用程序是在 Web 服務器上運行的軟件。終端用户通過 Web 瀏覽器訪問 Web 應用程序。Web 應用程序使用客户端—服務器（C/S）架構進行編程，該架構是用户（客户端）通過遠程服務器（可能由第三方託管）提供服務。Web API（應用程序編程接口）在整個 Web 上是可用的，用户可以通過 HTTP 協議訪問該接口，如圖 1 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-1-Web-Application-Programming-Interface300.jpg" alt="Figure 1: Web API"></p><p>本文將演示如何為地鐵設計一個基於 Web 的汽車自動智能停車系統。 它是使用開源的 Node-RED 設計。該系統使用模板節點創建了一個交互式的、時尚的用户登錄表單，用 HTML 和 CSS 編碼以獲取車主的詳細信息，從而實現停車系統的自動化。我們可以在圖 2 和圖 3 看到登錄表單和提交表單的流程圖。</p><p>使用的節點如下：</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/table-function-node-red.jpg" alt="table function"></p><h3 id="地鐵智能停車節點流程設計" tabindex="-1">地鐵智能停車節點流程設計 <a class="header-anchor" href="#地鐵智能停車節點流程設計" aria-label="Permalink to “地鐵智能停車節點流程設計”">​</a></h3><p>Node-RED 由 <code>node-red</code> 命令激活。訪問網址 <code>http://127.0.0.1:1880/</code> 可以看到 Node-RED 用户界面流程瀏覽器已經啓用，可以認為 Node-RED 設置已完成，可以正常工作了。</p><p>按照下面給出的步驟創建登錄表單和提交表單。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-2-Login-Form-Flow-Diagram300.jpg" alt="Figure 2: Login form flow diagram"></p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-3-Submission-Form-Flow-Diagram300.jpg" alt="Figure 3: Submission form flow diagram"></p><h3 id="登錄表單" tabindex="-1">登錄表單 <a class="header-anchor" href="#登錄表單" aria-label="Permalink to “登錄表單”">​</a></h3><p>1、在節點畫布中，拖放 <ruby>http 輸入<rt>http in</rt></ruby> 節點，這會為創建 Web 服務創建一個 HTTP 訪問點。</p><p>2、將 <ruby>http 輸入<rt>http in</rt></ruby> 節點連接到 <ruby>函數<rt>function</rt></ruby> 節點。函數節點有助於編寫 JavaScript 函數處理節點接收到的消息。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-4-Login-Form-of-Metro-Smart-Car-Parking300.jpg" alt="Figure 4: Login form for smart parking for cars"></p><p>3、將 <ruby>函數<rt>function</rt></ruby> 節點連接到 <ruby>模板<rt>template</rt></ruby> 節點，模板節點基於提供的模板創建一個 Web API。</p><p>4、將 <ruby>模板<rt>template</rt></ruby> 節點連接到 <ruby>http 響應<rt>http response</rt></ruby> 節點，它將響應 <ruby>http 輸入<rt>http in</rt></ruby> 節點的請求。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-5-Submission-Form-of-Metro-Smart-Car-Parking300.jpg" alt="Figure 5: Submission form for smart parking for cars"></p><h3 id="提交表單" tabindex="-1">提交表單 <a class="header-anchor" href="#提交表單" aria-label="Permalink to “提交表單”">​</a></h3><p>1、拖放 <ruby>http 輸入<rt>http in</rt></ruby> 節點並將其連接到 json 節點，json 節點將數據轉換為 JSON 字符串進行通信。</p><p>2、將 <ruby>http 輸入<rt>http in</rt></ruby> 節點連接到 <ruby>調試<rt>debug</rt></ruby> 節點，調試節點的調試監控器會輸出結果。</p><p>3、將 json 節點放置並連接到 <ruby>函數<rt>function</rt></ruby> 節點，將後者連接到 <ruby>http 響應<rt>http response</rt></ruby> 節點。</p><p>創建完整流程後，單擊 Node-RED 窗口右上角的 <ruby>部署<rt>Deploy</rt></ruby> 按鈕。訪問 <code>http://127.0.0.1:1880/ui/</code> 這個鏈接查看用户界面。</p><p>輸入鏈接然後單擊 <ruby>提交<rt>Submit</rt></ruby> 後，該鏈接會跳轉到下一頁，你可以在該頁面閲讀所有新聞。</p><h3 id="node-red-工作流程" tabindex="-1">Node-RED 工作流程 <a class="header-anchor" href="#node-red-工作流程" aria-label="Permalink to “Node-RED 工作流程”">​</a></h3><p>在單個 Node-RED 流程中，你可以創建登錄表單和提交表單，如圖 4 和圖 5 所示。</p><p>現在我們將配置節點屬性。</p><h4 id="登錄表單-1" tabindex="-1">登錄表單 <a class="header-anchor" href="#登錄表單-1" aria-label="Permalink to “登錄表單”">​</a></h4><p>編輯 <ruby>http 輸入<rt>http in</rt></ruby> 屬性：</p><ul><li><ruby>方法<rt>method</rt></ruby> 選擇 “Get”</li><li><ruby>網址<rt>URL</rt></ruby> 設為 <code>/MetroStation</code></li><li><ruby>名稱<rt>name</rt></ruby> 配置為 “<ruby>智能停車系統<rt>Smart Parking</rt></ruby>”。</li></ul><p>（LCTT 譯註：下文 http 響應節點的名稱為 Smart parking，p 字母小寫，為了區分，此處中文翻譯成智能停車系統。）</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-6-Http-in-Node-Property-Configurations300.jpg" alt="Figure 6: Http in node property configurations"></p><blockquote><p>注意：URL 可以使用任何用户定義的本地變量。</p></blockquote><p>現在選擇 <ruby>函數<rt>function</rt></ruby> 節點，編輯函數節點屬性：輸入代碼 <code>msg.url = project</code> ，並配置代碼 <ruby>名稱<rt>name</rt></ruby> 字段為 “<ruby>項目提交<rt>Project Submission</rt></ruby>”。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-7-Function-Node-Property-Configurations300.jpg" alt="Figure 7: Function node property configurations"></p><p>在 <ruby>模板<rt>template</rt></ruby> 節點的屬性窗口，為登錄表單配置相應的 HTML 代碼，並將代碼 <ruby>名稱<rt>name</rt></ruby> 命名為 “<ruby>顯示面板<rt>Display panel</rt></ruby>”。在此流程使用了 Mustache 模板格式（LCTT 譯註：Mustache 是鬍子的意思，因為它的嵌入標記 <code>{{ }}</code> 非常像鬍子）。Mustache 是一個簡單的 Web 模板系統，被描述為無邏輯的模板引擎。Mustache 沒有任何顯式的控制流語句，例如 <code>if</code> 和 <code>else</code> 條件和 <code>for</code> 循環。可以通過使用塊標籤處理列表和lambdas 來實現循環和條件評估。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-8-Template-Node-Property-Configurations300.jpg" alt="Figure 8: Template node property configurations"></p><p>配置編輯 <ruby>http 響應<rt>http response</rt></ruby> 節點的屬性，<ruby>名稱<rt>name</rt></ruby> 設為 “<ruby>智能停車<rt>Smart parking</rt></ruby>”（圖 9） 。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-9-Template-Node-Property-Configurations300.jpg" alt="Figure 9: Http response node property configurations"></p><h4 id="提交表單-1" tabindex="-1">提交表單 <a class="header-anchor" href="#提交表單-1" aria-label="Permalink to “提交表單”">​</a></h4><p>在 <ruby>http 輸入<rt>http in</rt></ruby> 節點的編輯屬性窗口，<ruby>方法<rt>method</rt></ruby> 選擇 “POST” ，<ruby>網址<rt>URL</rt></ruby> 設為 <code>/project</code>。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-10-Http-in-Node-Property-Configurations300.jpg" alt="Figure 10: Http in node property configurations"></p><p>在 JSON 節點的編輯窗口，<ruby>操作<rt>Action</rt></ruby>設為 “<ruby>JSON字符串與對象互轉<rt>Convert between JSON String &amp; Object</rt></ruby>”，參考圖 11。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-11-Json-Node-Property-Configurations300.jpg" alt="Figure 11: JSON node property configurations"></p><p><ruby>函數<rt>function</rt></ruby> 節點的配置如圖 12 所示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-12-Function-Node-Property-Configurations300.jpg" alt="Figure 12: Function node property configurations"></p><p>在 <ruby>http 響應<rt>http response</rt></ruby> 節點，編輯屬性 <ruby>名稱<rt>name</rt></ruby> 為 “<ruby>已提交項目<rt>Project Submitted</rt></ruby>”。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-13-Http-Response-Node-Property-Configurations300.jpg" alt="Figure 13: Http response node property configurations"></p><blockquote><p>注意：添加帶有評論的評論節點作為 “登錄表單” 和 “提交表單”。</p></blockquote><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-14-Debug-Node-Property-Configurations300.jpg" alt="Figure 14: Debug node property configurations"></p><h3 id="用户界面的控制面板" tabindex="-1">用户界面的控制面板 <a class="header-anchor" href="#用户界面的控制面板" aria-label="Permalink to “用户界面的控制面板”">​</a></h3><p>當用户單擊 <ruby>提交<rt>Submit</rt></ruby>，給出的數據將顯示在用户界面和調試節點。如果單擊 <ruby>重置<rt>Reset</rt></ruby>，詳細信息將被清除，允許用户輸入新的詳細信息（圖15）。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-15-User-Login-UI300.jpg" alt="Figure 15: User login UI"></p><p>地鐵停車費率通過超鏈接提供，收費表在用户界面顯示。因此，汽車智能停車系統通過適當的超鏈接實現自動化，展示地鐵站的停車費。該自動化系統的最終輸出可以在 Node-RED 控制面板的用户界面和調試監控器調取和展示。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/04/Figure-16-Parking-Tariff-Metro300.jpg" alt="Figure 16: Metro parking tariff"></p><hr>',58)),a("p",null,[r[1]||(r[1]=t("via: ",-1)),e(o,{href:"https://www.opensourceforu.com/2022/06/build-a-smart-parking-system-for-a-metro-station/"},{default:p(()=>[...r[0]||(r[0]=[t("https://www.opensourceforu.com/2022/06/build-a-smart-parking-system-for-a-metro-station/",-1)])]),_:1})]),a("p",null,[r[6]||(r[6]=t("作者：",-1)),e(o,{href:"https://www.opensourceforu.com/author/dr-maheswari-r/"},{default:p(()=>[...r[2]||(r[2]=[t("Dr Maheswari R.",-1)])]),_:1}),r[7]||(r[7]=t(" 選題：",-1)),e(o,{href:"https://github.com/lkxed"},{default:p(()=>[...r[3]||(r[3]=[t("lkxed",-1)])]),_:1}),r[8]||(r[8]=t(" 譯者：",-1)),e(o,{href:"https://github.com/Maisie-x"},{default:p(()=>[...r[4]||(r[4]=[t("Maisie-x",-1)])]),_:1}),r[9]||(r[9]=t(" 校對：",-1)),e(o,{href:"https://github.com/wxy"},{default:p(()=>[...r[5]||(r[5]=[t("wxy",-1)])]),_:1})]),a("p",null,[r[12]||(r[12]=t("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...r[10]||(r[10]=[t("LCTT",-1)])]),_:1}),r[13]||(r[13]=t(" 原創編譯，",-1)),e(o,{href:"https://linux.cn/"},{default:p(()=>[...r[11]||(r[11]=[t("Linux中國",-1)])]),_:1}),r[14]||(r[14]=t(" 榮譽推出",-1))])])}const F=n(b,[["render",d]]);export{S as __pageData,F as default};
